export type ConsoleAboutLinkListProps = Omit<ComponentPropsWithRef<'nav'>, 'children'> & {
	links: ConsoleAboutLink[];
	messages?: Pick<ConsoleAboutMessages, 'opensNewWindow'>;
};

export function ConsoleAboutLinkList({ className, links, messages, ...props }: ConsoleAboutLinkListProps) {
	return (
		<nav className={cn('divide-base-300 border-base-300 divide-y border-y', className)} {...props}>
			{links.map((link, index) => {
				const external = link.external ?? true;
				const target = link.target ?? (external ? '_blank' : undefined);
				const relTokens = new Set(link.rel?.split(/\s+/).filter(Boolean));
				if (target === '_blank') {
					relTokens.add('noopener');
					relTokens.add('noreferrer');
				}
				const rel = relTokens.size > 0 ? [...relTokens].join(' ') : undefined;
				return (
					<a
						key={link.id ?? index}
						href={link.href}
						target={target}
						rel={rel}
						aria-label={
							target === '_blank' ? `${link.label}，${messages?.opensNewWindow ?? '将在新窗口打开'}` : undefined
						}
						className='hover:text-primary focus-visible:ring-primary flex min-w-0 items-center gap-3 py-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-inset'
					>
						{hasRenderableNode(link.icon) ? <span className='shrink-0'>{link.icon}</span> : null}
						<span className='min-w-0 flex-1'>
							<span className='block font-medium'>{link.label}</span>
							{hasRenderableNode(link.description) ? (
								<span className='text-base-content/70 mt-0.5 block text-xs leading-5'>{link.description}</span>
							) : null}
						</span>
						{target === '_blank' ? <ExternalLink aria-hidden='true' className='size-3.5 shrink-0' /> : null}
					</a>
				);
			})}
		</nav>
	);
}

export type ConsoleAboutMaintainerListProps = ComponentPropsWithRef<'ul'> & {
	maintainers: ConsoleAboutMaintainer[];
};

export function ConsoleAboutMaintainerList({ className, maintainers, ...props }: ConsoleAboutMaintainerListProps) {
	return (
		<ul className={cn('divide-base-300 border-base-300 divide-y border-y', className)} {...props}>
			{maintainers.map((maintainer, index) => {
				const content = (
					<>
						{hasRenderableNode(maintainer.avatar) ? (
							<span className='bg-base-200 grid size-9 shrink-0 place-items-center rounded-full'>
								{maintainer.avatar}
							</span>
						) : null}
						<span className='min-w-0 flex-1'>
							<span className='block truncate text-sm font-medium'>{maintainer.name}</span>
							{hasRenderableNode(maintainer.role) ? (
								<span className='text-base-content/70 mt-0.5 block truncate text-xs'>{maintainer.role}</span>
							) : null}
						</span>
					</>
				);
				return (
					<li key={maintainer.id ?? index}>
						{maintainer.href ? (
							<a
								href={maintainer.href}
								target='_blank'
								rel='noopener noreferrer'
								className='hover:text-primary focus-visible:ring-primary flex items-center gap-3 py-3 outline-none focus-visible:ring-2 focus-visible:ring-inset'
							>
								{content}
								<ExternalLink aria-hidden='true' className='size-3.5 shrink-0' />
							</a>
						) : (
							<div className='flex items-center gap-3 py-3'>{content}</div>
						)}
					</li>
				);
			})}
		</ul>
	);
}

function ConsoleAboutStatusBadge({ status }: { status: ConsoleAboutStatus }) {
	const tones: Record<ConsoleAboutTone, string> = {
		neutral: 'badge-neutral',
		info: 'badge-info',
		success: 'badge-success',
		warning: 'badge-warning',
		error: 'badge-error',
	};
	return (
		<span className={cn('badge badge-sm gap-1', tones[status.tone ?? 'neutral'])}>
			{hasRenderableNode(status.icon) ? status.icon : null}
			{status.label}
		</span>
	);
}

function hasRenderableNode(value: ReactNode) {
	return value !== null && value !== undefined && value !== false;
}

'use client';

import type { ComponentPropsWithRef } from 'react';
import { useEffect, useState } from 'react';
import { cn } from '@/lib/utils';

export type ConsoleAboutClientSnapshot = {
	colorScheme?: 'dark' | 'light';
	devicePixelRatio?: number;
	language?: string;
	reducedMotion?: boolean;
	screen?: string;
	timezone?: string;
	userAgent?: string;
	viewport?: string;
};

export type ConsoleAboutClientMessages = {
	colorSchemeLabel: string;
	darkScheme: string;
	devicePixelRatioLabel: string;
	languageLabel: string;
	lightScheme: string;
	no: string;
	reducedMotionLabel: string;
	screenLabel: string;
	timezoneLabel: string;
	unavailable: string;
	userAgentSummary: string;
	viewportLabel: string;
	yes: string;
};

export type ConsoleAboutClientInfoProps = ComponentPropsWithRef<'div'> & {
	messages?: Partial<ConsoleAboutClientMessages>;
	showUserAgent?: boolean;
};

const defaultClientMessages: ConsoleAboutClientMessages = {
	colorSchemeLabel: '偏好主题',
	darkScheme: '暗色',
	devicePixelRatioLabel: '设备像素比',
	languageLabel: '语言',
	lightScheme: '亮色',
	no: '否',
	reducedMotionLabel: '减少动态效果',
	screenLabel: '屏幕',
	timezoneLabel: '时区',
	unavailable: '—',
	userAgentSummary: '查看用户代理',
	viewportLabel: '窗口',
	yes: '是',
};

export function ConsoleAboutClientInfo({
	className,
	messages: messageOverrides,
	showUserAgent = true,
	...props
}: ConsoleAboutClientInfoProps) {
	const [snapshot, setSnapshot] = useState<ConsoleAboutClientSnapshot>();
	const messages = { ...defaultClientMessages, ...messageOverrides };

	useEffect(() => {
		const update = () => setSnapshot(readClientSnapshot());
		const dark = getMediaQuery('(prefers-color-scheme: dark)');
		const reducedMotion = getMediaQuery('(prefers-reduced-motion: reduce)');
		update();
		window.addEventListener('resize', update);
		const unsubscribeDark = subscribeMediaQuery(dark, update);
		const unsubscribeReducedMotion = subscribeMediaQuery(reducedMotion, update);
		return () => {
			window.removeEventListener('resize', update);
			unsubscribeDark();
			unsubscribeReducedMotion();
		};
	}, []);

	const details = [
		[messages.viewportLabel, snapshot?.viewport],
		[messages.screenLabel, snapshot?.screen],
		[messages.devicePixelRatioLabel, snapshot?.devicePixelRatio],
		[messages.languageLabel, snapshot?.language],
		[messages.timezoneLabel, snapshot?.timezone],
		[
			messages.colorSchemeLabel,
			snapshot?.colorScheme
				? snapshot.colorScheme === 'dark'
					? messages.darkScheme
					: messages.lightScheme
				: undefined,
		],
		[
			messages.reducedMotionLabel,
			snapshot?.reducedMotion === undefined ? undefined : snapshot.reducedMotion ? messages.yes : messages.no,
		],
	] as const;

	return (
		<div className={cn('min-w-0', className)} {...props}>
			<dl className='border-base-300 grid border-y sm:grid-cols-2'>
				{details.map(([label, value], index) => (
					<div
						key={label}
						className={cn(
							'border-base-300 grid grid-cols-[7rem_minmax(0,1fr)] gap-3 border-b py-2.5 text-sm',
							'sm:px-3 sm:odd:border-r sm:odd:pl-0 sm:even:pr-0',
							index >= details.length - 2 && 'sm:border-b-0',
						)}
					>
						<dt className='text-base-content/70'>{label}</dt>
						<dd className='min-w-0 font-medium break-words'>{value ?? messages.unavailable}</dd>
					</div>
				))}
			</dl>
			{showUserAgent ? (
				<details className='border-base-300 mt-3 border-b pb-3'>
					<summary className='hover:text-primary focus-visible:ring-primary w-fit cursor-pointer text-sm font-medium outline-none focus-visible:ring-2'>
						{messages.userAgentSummary}
					</summary>
					<div className='bg-base-200/60 mt-2 overflow-x-auto rounded-sm p-3 font-mono text-xs leading-5 break-all'>
						{snapshot?.userAgent ?? messages.unavailable}
					</div>
				</details>
			) : null}
		</div>
	);
}

function readClientSnapshot(): ConsoleAboutClientSnapshot {
	const dark = getMediaQuery('(prefers-color-scheme: dark)');
	const reducedMotion = getMediaQuery('(prefers-reduced-motion: reduce)');
	return {
		viewport: `${window.innerWidth}×${window.innerHeight}`,
		screen: `${window.screen.width}×${window.screen.height}`,
		devicePixelRatio: window.devicePixelRatio,
		language: navigator.language,
		timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
		colorScheme: dark ? (dark.matches ? 'dark' : 'light') : undefined,
		reducedMotion: reducedMotion?.matches,
		userAgent: navigator.userAgent,
	};
}

function getMediaQuery(query: string) {
	return typeof window.matchMedia === 'function' ? window.matchMedia(query) : undefined;
}

function subscribeMediaQuery(query: MediaQueryList | undefined, listener: () => void) {
	if (!query) return () => undefined;
	if (typeof query.addEventListener === 'function') {
		query.addEventListener('change', listener);
		return () => query.removeEventListener('change', listener);
	}
	if (typeof query.addListener === 'function') {
		query.addListener(listener);
		return () => query.removeListener(listener);
	}
	return () => undefined;
}

